const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const states={active:'Active · matched automatically',awaiting:'Saved · awaiting your acceptance',correction:'Correction lesson · never reused as a skill',disabled:'Switched off'};
export function skillsHtml(view){
  return `<section class="wt-results"><h3>Skills learned from finished tasks</h3><p>Every real task that passes review saves a recipe here automatically: its method, checks and preferences. Matching skills help future work on this floor. Failed reviews stay as correction lessons. Your current brief and permissions always take priority.</p><label>Start using newly learned skills <select data-skill-policy><option value="owner" ${view.policy==='owner'?'selected':''}>After I accept the result</option><option value="review" ${view.policy==='review'?'selected':''}>After the agent review passes</option></select></label> <button data-tw="skill-policy">Save learning setting</button><p>This setting covers all halls. Saving skills adds no separate AI call; using them adds some prompt text. Skills stay in your settings backup even when old runs leave History. Original output files need your document backup.</p><label>Find a skill <input data-skill-query maxlength="120" value="${esc(view.query)}" placeholder="Search this floor’s skills"></label> <button data-tw="skill-search">Search</button><p>${view.total} saved · page ${view.page+1}</p>${view.skills.map(s=>`<article><h4>${esc(s.name)}</h4><p>${esc(states[s.state])} · ${esc(new Date(s.createdAt).toLocaleDateString('en-GB'))}</p><p>Used in ${s.uses||0} tasks · ${s.acceptedUses||0} later accepted · ${s.reworkUses||0} later needed rework. These counts do not prove the skill caused the result.</p><details><summary>Method, checks and source</summary><p>Use for: ${esc(s.when||s.task)}</p><ol>${s.steps.map(x=>`<li><b>${esc(x.title)}</b>${x.method?`<p>${esc(x.method)}</p>`:'<p>Older task: only the step title was retained.</p>'}${x.after.length?`<p>After: ${esc(x.after.join(', '))}</p>`:''}</li>`).join('')}</ol><p>Finished means: ${esc(s.checks)}</p><p>Checklist: ${esc(s.checklist||'Use the current task’s checks.')}</p><p>Preferences: ${esc(s.preferences||'Use the current brief.')}</p>${s.corrections.map(c=>`<p>Review correction: ${esc(c)}</p>`).join('')}${s.feedback?`<p>Your feedback: ${esc(s.feedback)}</p>`:''}<small>Source task: ${esc(s.runId)}</small>${s.source?` <button data-tw="openfile" data-path="${esc(s.source)}">Open source</button>`:''}</details><button data-tw="skill-toggle" data-skill="${esc(s.id)}" data-enabled="${s.disabled?'true':'false'}">${s.disabled?'Enable when eligible':'Switch off'}</button></article>`).join('')||'<p>No saved skills here yet. Complete a real Tower task to add one.</p>'}<p><button data-tw="skill-page" data-page="${view.page-1}" ${view.page===0?'disabled':''}>Newer</button> <button data-tw="skill-page" data-page="${view.page+1}" ${(view.page+1)*20>=view.total?'disabled':''}>Older</button></p></section>`;
}
